exec(open('/tmp/pocus-gen/c3/gen.py').read().split("# ---- variant builders")[0])
def tx(t,f="Geist",s=13,w=500,c="#8E8E93",ls=None,lh=None,extra=""):
    lh=lh or s+4; l=f"letter-spacing:{ls};" if ls else ""
    return f'<div style="font-family:{f};font-size:{s}px;font-weight:{w};line-height:{lh}px;{l}color:{c};{extra}">{t}</div>'
mono=lambda t,s,c="#F2F2F7",w=500,ls="-0.04em",extra="": tx(t,"Geist Mono",s,w,c,ls,None,extra)
pix=lambda t,s,c="#000000": tx(t,"Geist Pixel",s,400,c,None,s)
lab=lambda t,c="#6C6C70": tx(t.upper(),"Geist Mono",11,500,c,"0.08em",14)
def ticks(p,c,rgb,n=20,h=6,gap=3,off=None):
    k=round(p*n); off=off or f"rgba({rgb},0.2)"
    return f'<div style="display:flex;gap:{gap}px;">'+''.join(f'<div style="flex:1;height:{h}px;border-radius:2px;background:{c if i<k else off};"></div>' for i in range(n))+'</div>'
B="#4A8BE5"; BRGB="74,139,229"; BT="#172335"
ICON=lambda k,s=30,r=9,g=16,st="#000000",bg="rgba(0,0,0,0.13)": f'<div style="width:{s}px;height:{s}px;border-radius:{r}px;background:{bg};display:flex;align-items:center;justify-content:center;flex-shrink:0;"><svg width="{g}" height="{g}" viewBox="0 0 24 24" fill="none" stroke="{st}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{ICONS[k].replace("#000000",st)}</svg></div>'
STOPB=lambda s=52,c=B,bg="#000000": f'<div layer-name="Stop" style="width:{s}px;height:{s}px;border-radius:{s//2}px;background:{bg};display:flex;align-items:center;justify-content:center;flex-shrink:0;"><div style="width:{round(s*.3)}px;height:{round(s*.3)}px;border-radius:4px;background:{c};"></div></div>'
PLAYB=lambda s=40,bg="#000000",f="#FFFFFF": f'<div layer-name="Play" style="width:{s}px;height:{s}px;border-radius:{s//2}px;background:{bg};display:flex;align-items:center;justify-content:center;flex-shrink:0;"><svg width="{round(s*.32)}" height="{round(s*.37)}" viewBox="0 0 16 18" fill="{f}"><path d="M2 1.8c0-1 1.1-1.6 2-1.1l10.7 6.9c.8.5.8 1.7 0 2.2L4 16.7c-.9.5-2-.1-2-1.1z"/></svg></div>'
STATUS='<x-paper-clone node-id="2YU-0" />'

# ---------- 1 New tracker
P="#F07EB8"; PRGB="240,126,184"; PT="#3A1C2C"
MUSIC='<path d="M9 18V6l11-2v12"/><circle cx="6" cy="18" r="3"/><circle cx="17" cy="16" r="3"/>'
ICONS["music"]=MUSIC
backdrop=f'<div layer-name="Backdrop (Home dimmed)" style="position:absolute;left:0;top:0;right:0;height:420px;opacity:0.35;display:flex;flex-direction:column;"><x-paper-clone node-id="2YU-0" /><x-paper-clone node-id="2YN-0" /><div style="padding:4px 12px 0;"><x-paper-clone node-id="9HU-0" /></div></div>'
circ=lambda inner,bg="rgba(255,255,255,0.08)",s=44: f'<div style="width:{s}px;height:{s}px;border-radius:{s//2}px;background:{bg};display:flex;align-items:center;justify-content:center;flex-shrink:0;">{inner}</div>'
X='<svg width="13" height="13" viewBox="0 0 14 14" fill="none"><path d="M2 2l10 10M12 2 2 12" stroke="#FFFFFF" stroke-width="2.2" stroke-linecap="round"/></svg>'
CHK='<svg width="16" height="12" viewBox="0 0 16 12" fill="none"><path d="M1.5 6.5 6 11 14.5 1.5" stroke="#000000" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>'
preview=f'''<div layer-name="Preview — Guitar" style="display:flex;flex-direction:column;gap:10px;padding:5px 5px 12px;border-radius:26px;background:{PT};"><div style="display:flex;align-items:center;gap:12px;padding:12px 12px 12px 14px;border-radius:21px;background:{P};">{ICON("music",36,11,18)}<div style="flex:1;display:flex;flex-direction:column;gap:1px;"><div style="display:flex;align-items:center;gap:2px;">{tx("Guitar","Geist",18,600,"#000000","-0.015em",22)}<div style="width:2px;height:20px;background:#000000;"></div></div>{tx("Daily · 30m goal",s=13,c="rgba(0,0,0,0.62)")}</div>{mono("0:00",26,"#000000",ls="-0.05em")}{PLAYB()}</div><div style="padding:0 17px 0 19px;">{ticks(0,P,PRGB)}</div></div>'''
icons=''.join(circ(f'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="{"#000000" if k=="music" else "#8E8E93"}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{ICONS[k]}</svg>',P if k=="music" else "#1C1C1E",52).replace("border-radius:26px","border-radius:16px") for k in ["target","people","pulse","mail","book","music"])
cols=["#4A8BE5","#1DB3A6","#7CCB8E","#E9C95A","#F7A23A","#EF6B6B",P,"#9D68F0"]
colors=''.join(f'<div style="width:34px;height:34px;border-radius:17px;display:flex;align-items:center;justify-content:center;{"border:2px solid #F2F2F7;" if c==P else ""}"><div style="width:{24 if c==P else 28}px;height:{24 if c==P else 28}px;border-radius:14px;background:{c};"></div></div>' for c in cols)
seg=''.join(tx(p,"Geist Mono",12,600 if p=="DAY" else 500,"#000000" if p=="DAY" else "#8E8E93","0.06em",16,extra=f"flex:1;text-align:center;padding:10px 0;border-radius:12px;{'background:#F2F2F7;' if p=='DAY' else ''}") for p in ["DAY","WEEK","MONTH","YEAR"])
minus='<svg width="14" height="2" viewBox="0 0 14 2"><rect width="14" height="2" rx="1" fill="#FFFFFF"/></svg>'
plus='<svg width="14" height="14" viewBox="0 0 14 14" fill="none"><path d="M7 1v12M1 7h12" stroke="#FFFFFF" stroke-width="2" stroke-linecap="round"/></svg>'
sec=lambda l,body,pt=28: f'<div style="display:flex;flex-direction:column;gap:12px;padding:{pt}px 20px 0;">{lab(l)}{body}</div>'
sheet=f'''<div layer-name="Sheet" style="position:absolute;left:0;right:0;bottom:0;top:250px;display:flex;flex-direction:column;border-radius:30px 30px 0 0;background:#141416;"><div style="display:flex;justify-content:center;padding-top:8px;"><div style="width:40px;height:5px;border-radius:3px;background:rgba(255,255,255,0.18);"></div></div>
<div layer-name="Nav" style="display:flex;align-items:center;padding:12px 16px 0;">{circ(X)}<div style="flex:1;display:flex;justify-content:center;">{tx("New tracker","Geist",17,650,"#F2F2F7","-0.01em",22)}</div>{circ(CHK,P)}</div>
<div style="padding:22px 12px 0;">{preview}</div>
{sec("Icon",f'<div style="display:flex;justify-content:space-between;">{icons}</div>',26)}
{sec("Color",f'<div style="display:flex;justify-content:space-between;">{colors}</div>')}
{sec("Track per",f'<div style="display:flex;gap:4px;padding:4px;border-radius:16px;background:#1C1C1E;">{seg}</div>')}
<div style="display:flex;align-items:flex-end;justify-content:space-between;padding:28px 20px 0;"><div style="display:flex;flex-direction:column;gap:6px;">{lab("Goal per day")}{mono("0:30",36,"#F2F2F7")}</div><div style="display:flex;gap:10px;">{circ(minus,"#1C1C1E")}{circ(plus,"#1C1C1E")}</div></div></div>'''
NEW=backdrop+sheet

# ---------- 2 Lock screen live activity
la=f'''<div layer-name="Live Activity" style="display:flex;flex-direction:column;gap:10px;padding:5px 5px 12px;border-radius:26px;background:{BT};"><div style="display:flex;align-items:center;gap:12px;padding:14px 14px 14px 16px;border-radius:21px;background:{B};"><div style="flex:1;display:flex;flex-direction:column;gap:6px;"><div style="display:flex;align-items:center;gap:8px;">{ICON("target",24,7,13)}{tx("Deep Work","Geist",16,600,"#000000","-0.01em",20)}</div>{pix("00:50:01",52)}</div>{STOPB(52)}</div><div style="display:flex;flex-direction:column;gap:8px;padding:0 17px 0 19px;">{ticks(.91,B,BRGB)}<div style="display:flex;justify-content:space-between;">{mono("SINCE 20:06",10,"#8E8E93",ls="0.06em")}{mono("22:49 / 25:00",10,"#8E8E93",ls="0.02em")}</div></div></div>'''
LOCK=f'''{STATUS}<div layer-name="Clock" style="display:flex;flex-direction:column;align-items:center;gap:0;padding-top:14px;">{tx("Friday, 23 October","Geist",17,500,"rgba(255,255,255,0.7)",None,22)}{tx("20:56","Geist",104,700,"#F2F2F7","-0.03em",110)}</div><div style="flex:1;"></div><div style="padding:0 14px 120px;">{la}</div><div layer-name="Lock controls" style="position:absolute;left:44px;right:44px;bottom:34px;display:flex;justify-content:space-between;">{circ('<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#FFFFFF" stroke-width="2" stroke-linecap="round"><path d="M9 2h6v4l2 3v12a1 1 0 0 1-1 1H8a1 1 0 0 1-1-1V9l2-3z"/></svg>',"rgba(255,255,255,0.12)",50)}{circ('<svg width="20" height="18" viewBox="0 0 24 20" fill="none" stroke="#FFFFFF" stroke-width="2" stroke-linejoin="round"><path d="M3 6h4l2-3h6l2 3h4v12H3z"/><circle cx="12" cy="12" r="4"/></svg>',"rgba(255,255,255,0.12)",50)}</div>'''

# ---------- 3 Home widgets
DI=f'<div layer-name="Dynamic Island (compact)" style="position:absolute;left:50%;top:11px;width:190px;margin-left:-95px;height:36px;border-radius:18px;background:#000000;display:flex;align-items:center;justify-content:space-between;padding:0 14px 0 10px;">{ICON("target",20,6,11,B,f"rgba({BRGB},0.2)")}{mono("50:01",14,B,600,"-0.02em")}</div>'
def wrow(n,c,t,i):
    return f'<div style="display:flex;align-items:center;gap:10px;height:30px;">{ICON(i,22,7,12,c,"rgba(255,255,255,0.06)")}{tx(n,s=14,w=600,c="#AEAEB2",extra="flex:1;")}{mono(t,14,"#AEAEB2",ls="-0.02em")}{PLAYB(26,"rgba(255,255,255,0.1)","#FFFFFF")}</div>'
med=f'''<div layer-name="Widget — medium" style="display:flex;flex-direction:column;gap:8px;padding:5px 5px 10px;border-radius:26px;background:#1C1C1E;"><div style="display:flex;align-items:center;gap:10px;padding:10px 10px 10px 12px;border-radius:21px;background:{B};">{ICON("target",26,8,14)}<div style="flex:1;display:flex;flex-direction:column;">{tx("Deep Work","Geist",14,600,"#000000",None,18)}{tx("22:49 of 25h",s=11,c="rgba(0,0,0,0.6)",lh=14)}</div>{pix("50:01",34)}{STOPB(36)}</div><div style="display:flex;flex-direction:column;padding:2px 12px 0;">{wrow("Meetings","#F7A23A","5:24","people")}{wrow("Exercise","#1DB3A6","0:30","pulse")}{wrow("Email","#9D68F0","0:27","mail")}</div></div>'''
small_run=f'''<div layer-name="Widget — small (running)" style="width:182px;height:182px;display:flex;flex-direction:column;gap:10px;padding:5px 5px 12px;border-radius:26px;background:{BT};"><div style="flex:1;display:flex;flex-direction:column;justify-content:space-between;padding:12px;border-radius:21px;background:{B};"><div style="display:flex;justify-content:space-between;align-items:flex-start;">{ICON("target",26,8,14)}{STOPB(34)}</div><div style="display:flex;flex-direction:column;gap:2px;">{tx("Deep Work","Geist",13,600,"rgba(0,0,0,0.7)",None,16)}{pix("50:01",40)}</div></div><div style="padding:0 12px 0 14px;">{ticks(.91,B,BRGB,12,5,3)}</div></div>'''
EX="#1DB3A6"; EXRGB="29,179,166"; EXT="#0F2A29"
small_idle=f'''<div layer-name="Widget — small (idle)" style="width:182px;height:182px;display:flex;flex-direction:column;gap:10px;padding:5px 5px 12px;border-radius:26px;background:{EXT};"><div style="flex:1;display:flex;flex-direction:column;justify-content:space-between;padding:12px;border-radius:21px;background:{EX};"><div style="display:flex;justify-content:space-between;align-items:flex-start;">{ICON("pulse",26,8,14)}{PLAYB(34)}</div><div style="display:flex;flex-direction:column;gap:2px;">{tx("Exercise","Geist",13,600,"rgba(0,0,0,0.7)",None,16)}<div style="display:flex;align-items:baseline;gap:3px;">{mono("0:30",30,"#000000",ls="-0.05em")}{mono("/0:45",12,"rgba(0,0,0,0.55)",ls="-0.02em")}</div></div></div><div style="padding:0 12px 0 14px;">{ticks(.67,EX,EXRGB,12,5,3)}</div></div>'''
cap=lambda t: tx(t,s=12,c="#8E8E93",extra="text-align:center;")
dock='<div layer-name="Dock" style="position:absolute;left:14px;right:14px;bottom:14px;height:96px;border-radius:34px;background:rgba(255,255,255,0.08);display:flex;align-items:center;justify-content:space-around;">'+''.join('<div style="width:64px;height:64px;border-radius:16px;background:rgba(255,255,255,0.06);"></div>' for _ in range(4))+'</div>'
WID=f'''{STATUS}{DI}<div style="display:flex;flex-direction:column;gap:8px;padding:24px 26px 0;">{med}{cap("Chopped")}</div><div style="display:flex;gap:24px;padding:20px 26px 0;"><div style="display:flex;flex-direction:column;gap:8px;">{small_run}{cap("Chopped")}</div><div style="display:flex;flex-direction:column;gap:8px;">{small_idle}{cap("Chopped")}</div></div>{dock}'''

# ---------- 4 Dynamic island + controls
compact=f'<div style="display:flex;gap:10px;align-items:center;justify-content:center;"><div style="width:200px;height:38px;border-radius:19px;background:#000000;display:flex;align-items:center;justify-content:space-between;padding:0 14px 0 10px;">{ICON("target",22,7,12,B,f"rgba({BRGB},0.2)")}{mono("50:01",15,B,600,"-0.02em")}</div><div style="width:38px;height:38px;border-radius:19px;background:#000000;display:flex;align-items:center;justify-content:center;">{ICON("target",22,7,12,B,f"rgba({BRGB},0.2)")}</div></div>'
expanded=f'''<div style="display:flex;flex-direction:column;gap:14px;padding:18px 18px 16px;border-radius:44px;background:#000000;"><div style="display:flex;align-items:center;gap:12px;">{ICON("target",40,12,20)}<div style="flex:1;display:flex;flex-direction:column;gap:2px;">{tx("Deep Work","Geist",14,600,"#AEAEB2",None,18)}{pix("00:50:01",44,"#FFFFFF")}</div>{STOPB(52,"#000000",B)}</div><div style="display:flex;flex-direction:column;gap:6px;padding:0 4px;">{ticks(.91,B,BRGB,20,5,3,"#1C1C1E")}<div style="display:flex;justify-content:space-between;">{mono("SINCE 20:06",9,"#6C6C70",ls="0.06em")}{mono("22:49 / 25:00",9,"#6C6C70",ls="0.02em")}</div></div></div>'''
expanded=expanded.replace(f'background:{B};display:flex;align-items:center;justify-content:center;flex-shrink:0;"><div style="width:16px;height:16px;border-radius:4px;background:#000000','XX')
def cc(i,c,rgb,run=False,name=""):
    inner=(f'<div style="width:20px;height:20px;border-radius:5px;background:#000000;"></div>' if run else f'<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="{c}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{ICONS[i]}</svg>')
    return f'<div style="display:flex;flex-direction:column;align-items:center;gap:8px;"><div style="width:68px;height:68px;border-radius:34px;background:{c if run else "rgba(255,255,255,0.1)"};display:flex;align-items:center;justify-content:center;">{inner}</div>{tx(name,s=11,w=600,c="#F2F2F7" if run else "#8E8E93")}</div>'
lbl=lambda t: lab(t,"#6C6C70")
ISL=f'''<div style="display:flex;flex-direction:column;gap:14px;padding:32px 20px 0;align-items:center;">{lbl("Island · compact / minimal")}{compact}</div><div style="display:flex;flex-direction:column;gap:14px;padding:32px 12px 0;">{'<div style="display:flex;justify-content:center;">'+lbl("Island · expanded")+'</div>'}{expanded}</div><div style="display:flex;flex-direction:column;gap:16px;padding:32px 20px 32px;align-items:center;">{lbl("Control Center")}<div style="display:flex;gap:20px;">{cc("target",B,BRGB,True,"Deep Work")}{cc("pulse","#1DB3A6","",False,"Exercise")}{cc("mail","#9D68F0","",False,"Email")}</div></div>'''
for k,s in {"new":NEW,"lock":LOCK,"wid":WID,"isl":ISL}.items():
    s=s.replace("\n",""); open(f'{k}.html','w').write(s); print(k,len(s))
